<script setup lang="ts">
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ShieldCheck, LayoutDashboard, Files, Landmark, ScanText, BookOpenCheck, Sparkles, Grid2X2, Search, Bell, ChevronDown, ChevronRight, MapPin, CircleHelp, RotateCcw, Play, X, ArrowUpRight, Check, ListChecks, Shield, Menu } from 'lucide-vue-next'
import { usePlatformStore } from './stores/platform'
import Modal from './components/Modal.vue'
import StatusBadge from './components/StatusBadge.vue'
const route=useRoute(), router=useRouter(), store=usePlatformStore()
const nav=[{path:'/',label:'监督总览',icon:LayoutDashboard},{path:'/clues',label:'信访线索研判',icon:Files},{path:'/assets',label:'农村三资监督',icon:Landmark},{path:'/inspection',label:'巡察与整改',icon:ScanText},{path:'/review',label:'案卷审理助手',icon:BookOpenCheck},{path:'/assistant',label:'纪检 AI 助手',icon:Sparkles},{path:'/capabilities',label:'能力中心',icon:Grid2X2}]
const navGroups=[{label:'监督决策',number:'01',items:nav.slice(0,1)},{label:'业务工作台',number:'02',items:nav.slice(1,4)},{label:'专业工具',number:'03',items:nav.slice(4,7)}]
const currentGroup=computed(()=>navGroups.find(group=>group.items.some(item=>item.path===route.path))?.label||'工作空间')
const showSearch=ref(false),query=ref(''),showNotifications=ref(false),showReset=ref(false),showTasks=ref(false),showGuide=ref(false),guideIndex=ref(0),mobileNav=ref(false),showRole=ref(false),role=ref('演示专员')
const taskRoute:Record<string,string>={'信访线索':'/clues','农村三资':'/assets','巡察整改':'/inspection','AI助手':'/assistant'}
const guide=[{title:'从监督事项开始',text:'查看总览的优先处理事项，进入待研判的举报材料。',path:'/'},{title:'让原始材料变得清晰',text:'选择场地租赁线索，开始辅助研判，查看原文依据与疑似相关线索。',path:'/clues'},{title:'保留人工判断',text:'逐项核对提取信息与关联依据，保存摘要，经人工检查后提交复核；不自动创建核查任务。',path:'/clues'},{title:'穿透合同与收款',text:'核对应收 36,000 元、已关联 12,000 元及待核差额 24,000 元，再发起人工核查。',path:'/assets'},{title:'完成整改闭环',text:'批量阅卷后生成整改任务，补充说明与佐证，由人工复核销号。',path:'/inspection'},{title:'回到监督全局',text:'核对总览数据、核查任务及操作留痕，展示业务状态的实时联动。',path:'/'}]
const searchResults=computed(()=>{const q=query.value.trim();if(!q)return [];return [...store.clues.map(x=>({id:x.id,title:x.title,type:'信访线索',path:'/clues'})),...store.contracts.map(x=>({id:x.id,title:x.asset,type:'三资合同',path:'/assets'})),...store.issues.map(x=>({id:x.id,title:x.title,type:'巡察问题',path:'/inspection'}))].filter(x=>(x.title+x.id+x.type).includes(q))})
const activeTasks=computed(()=>store.tasks.filter(x=>x.status==='处理中'))
function visit(path:string,id?:string){router.push({path,query:id?{id}:{}});showSearch.value=false;mobileNav.value=false}
function goTask(task:any){showTasks.value=false;visit(taskRoute[task.source]||'/',task.sourceId)}
function keyboard(e:KeyboardEvent){if(route.meta.layout==='clues')return;if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();showSearch.value=!showSearch.value}}
onMounted(()=>window.addEventListener('keydown',keyboard));onUnmounted(()=>window.removeEventListener('keydown',keyboard))
function confirmReset(){store.reset();showReset.value=false;guideIndex.value=0;router.push('/')}
</script>
<template>
<RouterView v-if="route.meta.layout==='clues'"/>
<div v-else class="app-shell">
  <aside class="sidebar" :class="{'mobile-open':mobileNav}">
    <RouterLink to="/" class="brand"><span class="brand-symbol"><ShieldCheck :size="24" :stroke-width="1.8"/></span><div><strong>夏津纪检监察</strong><span>AI 智能辅助监督平台</span></div></RouterLink>
    <div class="workspace-tag"><span class="workspace-mark"><Landmark :size="15"/></span><span>县域监督工作台</span><span class="workspace-status">演示</span></div>
    <div class="nav-sections">
      <section v-for="group in navGroups" :key="group.label" class="nav-group">
        <div class="nav-label"><span>{{group.label}}</span><span class="group-number">{{group.number}}</span></div>
        <nav :aria-label="group.label"><RouterLink v-for="item in group.items" :key="item.path" :to="item.path" class="nav-item" :class="{selected:route.path===item.path}" @click="mobileNav=false"><span class="nav-icon"><component :is="item.icon" :size="18" :stroke-width="1.7"/></span><span>{{item.label}}</span><span v-if="item.path==='/clues'&&store.clues.filter(x=>x.status==='待研判').length" class="nav-count">{{store.clues.filter(x=>x.status==='待研判').length}}</span><span v-else-if="item.path==='/assistant'" class="ai-mini">AI</span><span v-else-if="route.path===item.path" class="selection-mark"></span></RouterLink></nav>
      </section>
      <section class="nav-group collaboration-group"><div class="nav-label"><span>协同管理</span><span class="group-number">04</span></div><button class="nav-item" @click="showTasks=true"><span class="nav-icon"><ListChecks :size="18" :stroke-width="1.7"/></span><span>我的核查任务</span><span v-if="activeTasks.length" class="nav-count">{{activeTasks.length}}</span></button><button class="nav-item" @click="showNotifications=true"><span class="nav-icon"><Shield :size="18" :stroke-width="1.7"/></span><span>操作留痕</span></button></section>
    </div>
    <div class="sidebar-bottom"><div class="sidebar-tools"><button @click="showGuide=true"><CircleHelp :size="16"/>演示帮助</button><button @click="showReset=true" title="重置演示数据"><RotateCcw :size="15"/>重置数据</button></div><div class="safety-caption"><span class="safety-dot"></span><span>本地演示 · 全部数据虚构</span></div></div>
  </aside>
  <div class="workspace">
    <header class="topbar"><div class="breadcrumb"><button class="mobile-toggle" @click="mobileNav=!mobileNav" aria-label="展开导航"><Menu :size="20"/></button><span>{{currentGroup}}</span><ChevronRight :size="14"/><strong>{{route.meta.title}}</strong></div><div class="global-actions"><div class="environment-label"><span class="environment-dot"></span><div><strong>本地演示</strong><span>夏津县 · 虚构样例数据</span></div></div><button class="search-button" aria-label="全局搜索" @click="showSearch=true"><Search :size="17"/><span>搜索工作空间</span><kbd>⌘ K</kbd></button><button class="topbar-guide" @click="showGuide=!showGuide"><Play :size="14"/>演示导览</button><button class="notification-button" aria-label="通知与操作留痕" @click="showNotifications=true"><Bell :size="19"/><i v-if="store.events.length"></i></button><span class="header-separator"></span><div class="user-control"><button @click="showRole=!showRole" class="user-button"><span class="avatar">{{role[0]}}</span><span class="user-copy"><strong>{{role}}</strong><span>模拟工作角色</span></span><ChevronDown :size="14"/></button><div v-if="showRole" class="role-menu"><p>切换演示角色</p><button v-for="r in ['演示专员','研判人员','巡察人员','管理员']" :key="r" @click="role=r;showRole=false;store.addEvent('切换演示角色',r)">{{r}}<Check v-if="role===r" :size="14"/></button></div></div></div></header>
    <main class="main-content"><section v-if="showGuide" class="guide-panel panel" aria-label="演示导览"><div class="guide-topline"><span class="guide-label"><Play :size="15"/>现场演示导览</span><span class="guide-count">第 {{guideIndex+1}} 步 / 共 6 步</span><div class="guide-dots"><button v-for="(_,i) in guide" :class="{active:i===guideIndex,done:i<guideIndex}" @click="guideIndex=i" :aria-label="`演示第 ${i+1} 步`">{{i+1}}</button></div><button class="guide-close" aria-label="收起导览" @click="showGuide=false"><X :size="17"/></button></div><div class="guide-body"><div class="guide-description"><h3>{{guide[guideIndex]!.title}}</h3><p>{{guide[guideIndex]!.text}}</p></div><div class="guide-actions"><button class="btn btn-quiet" :disabled="guideIndex===0" @click="guideIndex--">上一步</button><button class="btn btn-primary" @click="visit(guide[guideIndex]!.path);if(guideIndex<5)guideIndex++;else showGuide=false">{{guideIndex===5?'返回总览并结束':'前往此场景'}} <ChevronRight :size="15"/></button></div></div></section><RouterView v-slot="{Component}"><component :is="Component" :key="route.path"/></RouterView><footer class="workspace-footer"><span>夏津县纪检监察 AI 智能辅助监督平台</span><span><ShieldCheck :size="13"/> AI 辅助结果须经人工复核</span></footer></main>
  </div>


  <Modal v-if="showSearch" title="搜索工作空间" @close="showSearch=false"><div class="field search-field"><input v-model="query" placeholder="搜索线索、合同、巡察问题或编号…" autofocus aria-label="全局搜索关键词"></div><p v-if="!query" class="search-hint">试试「租赁」「补贴」或「SZ-HT-2026-018」</p><div v-else-if="!searchResults.length" class="empty">没有匹配记录，请更换关键词。</div><button v-for="result in searchResults" :key="result.id" class="search-result" @click="visit(result.path,result.id)"><span><small>{{result.type}} · {{result.id}}</small><strong>{{result.title}}</strong></span><ChevronRight :size="17"/></button></Modal>
  <Modal v-if="showReset" title="重置演示数据？" @close="showReset=false"><p class="muted">本次演示创建的核查任务、研判结果和整改记录将恢复为初始样例。此操作仅影响本浏览器的虚构演示数据。</p><div class="modal-actions"><button class="btn" @click="showReset=false">保留当前进度</button><button class="btn btn-primary" @click="confirmReset">确认重置</button></div></Modal>
  <Modal v-if="showTasks" title="我的核查任务" @close="showTasks=false"><p class="muted">{{activeTasks.length}} 项正在处理 · 所有任务均由人工确认创建</p><div v-if="!store.tasks.length" class="empty"><ListChecks :size="32"/>还没有核查任务<p>在信访、三资或巡察场景中确认后，任务将在此同步。</p></div><div v-for="task in store.tasks" :key="task.id" class="task-item"><div class="section-head"><span class="eyebrow">{{task.id}}</span><StatusBadge :status="task.status"/></div><h3>{{task.title}}</h3><p class="muted">{{task.assignee}} · 截止 {{task.deadline}}</p><div class="task-actions"><button class="btn btn-link" @click="goTask(task)">查看业务依据 <ArrowUpRight :size="14"/></button><button v-if="task.status==='处理中'&&task.source!=='巡察整改'" class="btn btn-sm" @click="store.completeTask(task.id)"><Check :size="14"/>人工确认完成核查</button></div></div></Modal>
  <Modal v-if="showNotifications" title="通知与操作留痕" @close="showNotifications=false"><p class="muted">本地操作记录 · 演示留痕，不代表生产安全审计</p><div v-if="!store.events.length" class="empty"><ShieldCheck :size="32"/>暂无操作记录，开始一次辅助研判试试。</div><div v-for="event in store.events.slice(0,30)" :key="event.id" class="audit-item"><span class="audit-point"></span><div><strong>{{event.action}}</strong><p>{{event.detail}}</p><time>{{event.time}}</time></div></div></Modal>
</div>
